/**
 * dsh-mcp-manager — workspace/impl/full-name/index.ts：server 全名与工具名归一化。
 *
 * 阶段 4 自 src/middleware-utils.ts 迁入工作空间路由域（命名/全名解析类，
 * v3 §二 workspace/full-name.ts）；策略裁决与目录检索函数留在
 * middleware-utils.ts（阶段 5 catalog 域迁出）。引用面经 workspace/interface.ts。
 */

import { MIDDLEWARE_GLOBAL_ROOT } from "../../../../shared/interface.ts";

/** server 全局唯一名：@<root>/<server>。 */
export function fullServerName(root: string, server: string): string {
  return `@${root}/${server}`;
}

/** 解析 @<root>/<server> 全名 → { root, server }；非法返回 undefined。
 * root 是绝对路径（以 / 开头），故从最后一个 `/` 分割（server 名不含 `/`）。
 * 特殊形态兼容：`@global/<server>`（单 @，人类/文档/A2 指引形态）归一化为
 * root=`@global`（MIDDLEWARE_GLOBAL_ROOT）；`@@global/<server>`（双 @，内部
 * fullServerName 产物）同样归一化为 `@global`——两种输入等价，杜绝「单 @ 被
 * 路由拒绝、双 @ 放行」的语义分裂（隔离验证 P0 发现，smoke 双 @ 掩盖单 @ 被拒）。 */
export function parseFullServerName(name: string): { root: string; server: string } | undefined {
  if (!name.startsWith("@")) return undefined;
  const slash = name.lastIndexOf("/");
  if (slash <= 1 || slash === name.length - 1) return undefined;
  const rawRoot = name.slice(1, slash);
  // @global/<s> → rawRoot="global"；@@global/<s> → rawRoot="@global"。
  const root = rawRoot === "global" || rawRoot === "@global" ? MIDDLEWARE_GLOBAL_ROOT : rawRoot;
  return { root, server: name.slice(slash + 1) };
}

/** 提取裸名（@root/server → server；无前缀原样返回）。 */
export function bareServerName(name: string): string {
  const parsed = parseFullServerName(name);
  return parsed?.server ?? name;
}

/** 归一化中间层工具的 tool 参数（模型可能传 mcp__<id>__<tool> 直呼全名）。
 * @param caller 调用方工具名（错误文案前缀；ws_mcp_call / ws_mcp_detail 复用）。 */
export function normalizeToolName(
  serverName: string,
  toolName: string,
  caller = "ws_mcp_call",
): string {
  const prefix = `mcp__${serverName}__`;
  let name = toolName;
  if (name.startsWith("mcp__")) {
    while (name.startsWith(prefix)) name = name.slice(prefix.length);
    if (name.startsWith("mcp__")) {
      throw new Error(
        `${caller}: tool 参数疑似其他 MCP server 的注册全名（${JSON.stringify(toolName)}，server="${serverName}"）；请传该 server 上的裸名`,
      );
    }
  }
  return name;
}

/**
 * dsh-mcp-manager — workspace/impl/root-resolution/index.ts：项目根发现与执行路由解析。
 *
 * 阶段 4 自 src/manager.ts（findProjectRoot/normalizedProjectRoot 方法）与
 * src/apply-runtime.ts（makeResolveRoot）迁入工作空间路由域，纯函数化
 * （不再依赖 manager 实例）；B3 修复（空 cwd 回落含 runtime 源）落位
 * makeResolveRoot。引用面经 workspace/interface.ts。
 */

import { existsSync, realpathSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { dshHome } from "../../../../../../../shared/dsh-home.js";
import type { McpManager } from "../../../connection/interface.ts";
import { MIDDLEWARE_GLOBAL_ROOT } from "../../../../shared/interface.ts";

/** DSH 全局家目录（shared/dsh-home.js 语义：DSH_HOME 非空白原样采用、空白
 *  视同未设置回落 ~/.dsh；#517 收敛）。resolve 为本处 .dsh 标记排除的对比
 *  用途服务。 */
function dshHomePath() {
  return resolve(dshHome());
}

/** 项目根发现：从 cwd 向上找 .git / .dsh / .mcp.json 标记，找不到用 cwd 本身。
 *  .dsh 标记须排除 DSH 全局家目录（默认 ~/.dsh，尊重 DSH_HOME）——否则 home
 *  下任何无标记目录（如 ~/dev/leetcode）向上都会命中 ~/.dsh，把 home 误判为
 *  项目根并加载 ~/.dsh/@wingsky-1/dsh-mcp-manager/mcp.json，导致别的会话串入不属于它的项目级 MCP。 */
export async function findProjectRoot(cwd: string | undefined): Promise<string> {
  const home = dshHomePath();
  let current = resolve(cwd ?? process.cwd());
  for (let depth = 0; depth < 16; depth += 1) {
    const dotDsh = join(current, ".dsh");
    // .dsh 目录存在且不是 DSH 全局家目录才算项目标记。
    const hasProjectDsh = existsSync(dotDsh) && resolve(dotDsh) !== home;
    if (
      existsSync(join(current, ".git")) ||
      hasProjectDsh ||
      existsSync(join(current, ".mcp.json"))
    ) {
      return current;
    }
    const parent = dirname(current);
    if (parent === current) break;
    current = parent;
  }
  return resolve(cwd ?? process.cwd());
}

/** 归一化项目根（realpath；失败回退 resolve）。中间层路由使用。 */
export async function normalizedProjectRoot(cwd: string | undefined): Promise<string | undefined> {
  if (cwd === undefined || cwd === null || cwd === "") return undefined;
  const root = await findProjectRoot(cwd);
  // 同一项目经符号链接进入时拼写不同，收敛到同一键防止连接池分裂。
  try {
    return realpathSync(root);
  } catch {
    return root;
  }
}

/** resolveRoot 路由：exec.agent → 归一化项目根（agent-less → undefined）。 */
export function makeResolveRoot(
  manager: McpManager,
): (agent: unknown) => Promise<string | undefined> {
  // 路由输入：exec.agent 当前 cwd = agent.session.header.cwd（实证已闭合）。
  // 单池（#767 笔 1a）：项目根解析不出时**无条件**回落全局虚拟 root @global
  // （可达性三件套之二）。全局服务器不再有 mcp__ 直呼面，@global 不可达即等于
  // 它们不可达——这道门不再是模式分支。
  return async (agent: unknown): Promise<string | undefined> => {
    if (typeof agent !== "object" || agent === null) return undefined;
    const session = (agent as { session?: { header?: { cwd?: unknown } } }).session;
    const cwd = session?.header?.cwd;
    const root = await normalizedProjectRoot(typeof cwd === "string" ? cwd : undefined);
    if (root !== undefined) return root;
    // B3（requirements 8.1 纠偏）：回落查 projectServersFor("@global")（含
    // runtime 注入并集，#413）而非 globalServers()（仅 store.data.servers）——
    // 否则仅 runtime 注入服务器时回落失败「无法确定工作空间」。
    const globalServers = ((await manager.projectServersFor(MIDDLEWARE_GLOBAL_ROOT)) ?? []).filter(
      (server) => server.enabled !== false,
    );
    if (globalServers.length > 0) return MIDDLEWARE_GLOBAL_ROOT;
    return undefined;
  };
}

/**
 * dsh-mcp-manager — workspace/impl/scope/index.ts：scope 归一化（域内实现）。
 *
 * scope 常量 "global"/"project" 的**物理定义已上移 shared/constants.ts**：客户端把它们以
 * 字面量重复实现（src/client/core/api.ts），故它们是跨端契约而非宿主内部常量（W3b）。本文件
 * 保留 normalizeScope 并转出两个常量，目录外引用面仍经 workspace/interface.ts。
 *
 * 历史：scope 字符串曾在宿主/监督器/路由硬编码 25+ 处，独立成模块以避免
 * index.js ↔ supervisor/routes 的循环依赖；阶段 4 自 src/scope.ts 迁入 workspace 域。
 */

import { SCOPE_GLOBAL, SCOPE_PROJECT } from "../../../../shared/interface.ts";

export { SCOPE_GLOBAL, SCOPE_PROJECT };

/** 归一化 scope（非法值回落 global）。 */
export function normalizeScope(value: string): "global" | "project" {
  return value === SCOPE_PROJECT ? SCOPE_PROJECT : SCOPE_GLOBAL;
}

/**
 * dsh-mcp-manager — workspace/impl/server-id/index.ts：(scope, name) → 注册名 id 的内存表。
 *
 * 为什么需要这层映射：官方 dsh-mcp-client 的 serverName 在 `scopeOf(ctx) ?? ctx.root` 这个**整个
 * 应用根**上活体预留，同 owner 重名当场抛（spike3 实测）；而「同一 bare 名在全局与某项目都配」是
 * 常见写法——照现状语义（先到先得、后到跳过）就等于跨 root 的同名服务器只能有一个生效，按 root 给
 * 名字加后缀又会把项目路径摘要进模型可见的工具名。折中是给每个 (scope, name) 分配一个与用户配置
 * 解耦的随机短串：官方侧不再有重名，`mcp__<id>__<tool>` 也不泄漏路径（767-v6-STAGED-PLAN §2.6
 * 裁定 B、S1-ENGINE-SWAP-DESIGN §1.7）。
 *
 * scope 是**装载作用域标识**，本包传 root（项目根绝对路径或 @global）。为什么不是 global/project
 * 词表：判重面按 root 分开，跨 root 同名各自成条正是本表要提供的改进，用词表会把两个项目的同名
 * 服务器又并成一条。
 *
 * 稳定性语义：同一 (scope, name) 在一次进程内恒得同一个 id；跨进程不承诺稳定。表是纯内存态，
 * 不落盘、不进任何持久化键——正因如此，id 可以随时重生成而不牵动用户配置与 last-good 缓存。
 *
 * 生成器经工厂入参注入：测试要能造确定性 id，也要能造出可控的冲突序列。映射与已占用面都是**实例
 * 字段**——模块级可变计数器被 gate:module-state 明禁，且模块级表会让同进程的两次装配共享状态。
 */
import { randomBytes } from "node:crypto";
import { SERVER_NAME_PATTERN } from "../../../shared/interface.ts";

/** id 生成器：每次调用产出一个候选 id。注入点只为可测（确定性 id / 冲突序列）。 */
export type ServerIdFactory = () => string;

/** 分配入参。`idFactory` 省略时用默认随机实现。 */
export interface ServerIdTableOptions {
  idFactory?: ServerIdFactory;
}

/** (scope, name) → id 的查询面；id 在首次查询时分配并自此固定。 */
export interface ServerIdTable {
  /** 取该 (scope, name) 的 id；未分配则生成并记住。同参恒同值。 */
  idFor(scope: string, name: string): string;
  /** 该 (scope, name) 是否已分配 id（只读查询，不触发分配）。 */
  has(scope: string, name: string): boolean;
}

/**
 * 冲突重试上界。默认生成器每次独立取 72 bit 随机量，真实碰撞可忽略不计；上界的意义是让**注入的**
 * 恒定生成器变成一条诚实的报错，而不是把装配卡死在死循环里。
 */
const ATTEMPT_LIMIT = 64;

/** 默认 id 生成器：9 字节随机量 → base64url 12 字符，落在官方字符集内且无填充。 */
function defaultServerIdFactory(): string {
  return randomBytes(9).toString("base64url");
}

/** 候选值准入：官方 Config 的 serverName 会同时进 `mcp__<id>__` 前缀与插件注册面，字符集与长度只能
 *  照 SERVER_NAME_PATTERN（与官方同源的单一物理定义，见 server/shared/constants.ts）。非字符串必须
 *  先挡：正则对入参做隐式字符串化，`undefined` 恰好匹配该字符集，不挡就静默放行一个非法 id。 */
function isUsableId(candidate: unknown): candidate is string {
  return typeof candidate === "string" && SERVER_NAME_PATTERN.test(candidate);
}

/**
 * 建一张独立的 id 表。每次调用得到互不相通的映射与已占用面（I9：同进程两次装配不得共享状态）。
 */
export function makeServerIdTable(options: ServerIdTableOptions = {}): ServerIdTable {
  const idFactory = options.idFactory ?? defaultServerIdFactory;
  // 按 scope 分表而非拼成一个键：name 是用户输入，任何分隔符都可能被它自己撞出歧义。
  const idByScope = new Map<string, Map<string, string>>();
  // 已分配 id 面：官方按注册名预留，同表内必须唯一。
  const assigned = new Set<string>();
  return {
    idFor(scope: string, name: string): string {
      let scopeTable = idByScope.get(scope);
      if (scopeTable === undefined) {
        scopeTable = new Map<string, string>();
        idByScope.set(scope, scopeTable);
      }
      const assignedId = scopeTable.get(name);
      if (assignedId !== undefined) return assignedId;
      for (let attempt = 0; attempt < ATTEMPT_LIMIT; attempt += 1) {
        const candidate = idFactory();
        if (!isUsableId(candidate)) {
          throw new Error(
            `server id 生成器产出不满足 SERVER_NAME_PATTERN 的候选值：${JSON.stringify(candidate)}`,
          );
        }
        if (assigned.has(candidate)) continue;
        assigned.add(candidate);
        scopeTable.set(name, candidate);
        return candidate;
      }
      throw new Error(
        `server id 分配失败：${ATTEMPT_LIMIT} 次候选值均与已分配 id 冲突（scope=${scope}，name=${name}）`,
      );
    },
    has(scope: string, name: string): boolean {
      return idByScope.get(scope)?.has(name) ?? false;
    },
  };
}

