    const fixture = sessionFixture();
    await fixture.manager.initMiddleware();
    await fixture.manager.setSession(fixture.proj);
    const sameStore = fixture.manager.projectStore;
    // 切走：项目 supervisor 全部断开（无标记目录回落为项目根 = cwd 自身，
