    expect(state.disposers.length).toBe(1);
    for (const disposeEffect of [...state.disposers]) disposeEffect();
  });

  // announceToAgent:false：有路由无 section；announceCatalog:false：无 pre-step。
  const disabledAnnounce = () =>
    applied({
