describe("#903 M4：projectUnitFor 后台连接失败记 warn", () => {
  it("后台 ensureConnected 翻错 → warn 落日志（把 .catch 删掉即无 warn 红）", async () => {
    const servers: ServerConfig[] = [
      { name: "ctx", transport: "stdio", command: "npx", enabled: true },
    ];
