        info: () => {},
        warn: (message: string): void => {
          warns.push(message);
        },
        error: () => {},
      },
    };
    const mw = trackMw(new McpMiddleware(capturingHost as unknown as MiddlewareHost));
    mw.ensureConnected = async () => {
      throw new Error("boom-bg");
