  });

  it("数组顶层 → must be an object", () => {
    expect(() => parseClaudeJson("[1]")).toThrow(/must be an object/);
  });

  it("null 顶层 → must be an object", () => {
    expect(() => parseClaudeJson("null")).toThrow(/must be an object/);
  });

  it("字符串顶层 → must be an object", () => {
