    }
  });

  it("命中：MY_TOKEN / MY_SECRET / GITHUB_TOKEN / CONTEXT7_API_KEY / Authorization", () => {
    for (const name of [
      "MY_TOKEN",
      "MY_SECRET",
      "TOKEN",
      "SECRET",
      "KEY",
      "GITHUB_TOKEN",
      "CONTEXT7_API_KEY",
      "Authorization",
      "authorization",
      "AWS_CREDENTIALS",
      "API_KEYS",
      "TOKEN2",
      "X-PASSWD",
      "my-auth-token",
    ]) {
      expect(isSecretEnvName(name), `${name} 须判凭据形`).toBe(true);
    }
  });

  it("R5：MYAPIKEY 无分隔符粘连仍判否（宁漏不误伤，防词表膨胀静默翻转）", () => {
