    // 若未来有人把 MYAPIKEY 收进词表，此断言变红即显式复核点。
    expect(isSecretEnvName("MYAPIKEY")).toBe(false);
  });

  it("豁免：DSH_HOME 大小写皆放行；正当名 DEBUG / PATH 放行；非字符串/空串判否", () => {
