    store: {} as never,
    catalogCache: new Map(),
  } as unknown as RoutesManager;
}

describe("#770-A2 路由错误边界脱敏", () => {
  it("含凭据的控制器错误经 handleError 被抹（GET /servers 摘要抛错）", async () => {
    installAll();
