    expect(status).toBe(400);
    const body = payload as { error?: string };
    expect(body.error).not.toContain(A2_SECRET);
    expect(body.error).toContain("[REDACTED]");
  });

  it("无秘密的 400 错误脱敏恒等无害（原文原样返回）", async () => {
    installAll();
